#!/usr/bin/env python3
"""Differential check of the records generated by in_tail.

Two binaries read the same corpus under several configurations (plain lines,
custom keys, long lines, multiline parsers, parsers) and the raw msgpack they
deliver must be identical byte per byte once the timestamps are masked.

Usage: ./tail_encoding_diff.py <reference fluent-bit> <candidate fluent-bit>
"""
import os, subprocess, sys, tempfile, random

import msgpack

PARSERS = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parsers.conf")

def run(binary, logfile, outdir, extra):
    conf = os.path.join(outdir, "flb.conf")
    open(conf, "w").write(f"""[SERVICE]
    flush 0.2
    log_level error
    grace 1
    parsers_file {PARSERS}
[INPUT]
    name tail
    path {logfile}
    read_from_head true
    exit_on_eof true
    buffer_chunk_size 32k
{extra}
[OUTPUT]
    name file
    match *
    path {outdir}
    file out.mp
    format msgpack
""")
    r = subprocess.run([binary, "-c", conf], stdout=subprocess.PIPE,
                       stderr=subprocess.STDOUT, timeout=120)
    if not os.path.exists(os.path.join(outdir, "out.mp")):
        print("NO OUTPUT from", binary, "rc", r.returncode)
        print(r.stdout.decode()[-1500:])
        sys.exit(2)
    data = open(os.path.join(outdir, "out.mp"), "rb").read()
    # walk records, mask the 8 timestamp bytes of each
    out = bytearray(data)
    up = msgpack.Unpacker(raw=True, max_buffer_size=0)
    up.feed(data)
    pos = 0
    n = 0
    for _ in up:
        assert data[pos:pos + 4] == b"\x92\x92\xd7\x00", data[pos:pos + 4]
        out[pos + 4:pos + 12] = b"\0" * 8
        pos = up.tell()
        n += 1
    assert pos == len(data)
    return bytes(out), n

def main():
    base, new = sys.argv[1], sys.argv[2]
    rnd = random.Random(7)
    with tempfile.TemporaryDirectory(dir="/dev/shm") as d:
        logfile = os.path.join(d, "in.log")
        with open(logfile, "wb") as f:
            for i in range(20000):
                kind = rnd.randrange(12)
                if kind == 0:
                    f.write(b"\n")
                elif kind == 1:
                    f.write(b"crlf line %d\r\n" % i)
                elif kind == 2:
                    f.write(("utf8 áé中文 %d\n" % i).encode())
                elif kind == 3:
                    f.write(b"y" * rnd.choice([31, 32, 255, 256, 65535, 65536, 70000]) + b"\n")
                elif kind == 4:
                    f.write(b"\r\n")
                elif kind in (5, 6):
                    f.write(b"2026-11-15T10:00:00.%06dZ stdout %s cri msg %d\n" % (i, b"P" if i % 7 == 0 else b"F", i))
                elif kind == 8:
                    f.write(b'{"time":"2026-11-15T10:00:00.%06dZ","n":%d,"f":1.5,"neg":-70000,"big":18446744073709551615,"nested":{"a":[1,2,{"b":null}],"t":true},"s":"%s"}\n' % (i, i, b"z" * rnd.randrange(300)))
                elif kind == 9:
                    f.write(b'key%d=val%d other="quoted v" n=%d\n' % (i, i, i))
                elif kind == 7:
                    f.write(b'{"log":"docker msg %d\\n","stream":"stderr","time":"2026-11-15T10:00:00.%06dZ"}\n' % (i, i))
                else:
                    f.write(b"line %d " % i + b"x" * rnd.randrange(200) + b"\n")
        ok = True
        for name, extra in [("plain", "    buffer_max_size 512k\n"),
                            ("keys", "    buffer_max_size 512k\n    path_key file\n    offset_key off\n    key msg\n"),
                            ("skip_empty", "    buffer_max_size 512k\n    skip_empty_lines on\n    offset_key off\n"),
                            ("long", "    skip_long_lines on\n    buffer_max_size 64k\n    path_key p\n"),
                            ("cri", "    buffer_max_size 512k\n    multiline.parser cri\n"),
                            ("cri-keys", "    buffer_max_size 512k\n    multiline.parser cri\n    path_key file\n    offset_key off\n"),
                            ("docker-keys", "    buffer_max_size 512k\n    multiline.parser docker\n    path_key file\n"),
                            ("p-json", "    buffer_max_size 512k\n    parser json\n"),
                            ("p-json-keys", "    buffer_max_size 512k\n    parser json_notime\n    path_key file\n    offset_key off\n"),
                            ("p-regex-keys", "    buffer_max_size 512k\n    parser rx\n    offset_key off\n"),
                            ("p-types", "    buffer_max_size 512k\n    parser rx_types\n    path_key f\n"),
                            ("p-logfmt", "    buffer_max_size 512k\n    parser lf\n"),
                            ("truncate", "    truncate_long_lines on\n    buffer_max_size 64k\n")]:
            res = []
            for b in (base, new):
                o = os.path.join(d, name + "-" + os.path.basename(b))
                os.makedirs(o)
                res.append(run(b, logfile, o, extra))
            same = res[0] == res[1]
            ok &= same
            print(f"{name:12s} records={res[0][1]}/{res[1][1]} bytes={len(res[0][0])}/{len(res[1][0])} identical={same}")
        sys.exit(0 if ok else 1)
main()
